import{_ as e,o,c as r,a2 as a}from"./chunks/framework.CqdVOxXJ.js";const u=JSON.parse(`{"title":"What's new","description":"","frontmatter":{},"headers":[],"relativePath":"whats-new.md","filePath":"whats-new.md","lastUpdated":1793268728000}`),n={name:"whats-new.md"};function s(i,t,d,h,l,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="what-s-new" tabindex="-1">What&#39;s new <a class="header-anchor" href="#what-s-new" aria-label="Permalink to &quot;What&#39;s new&quot;">​</a></h1><p>Changes to Rakkii Ops that this guide now covers. Dates are when the change reached the integration app.</p><h2 id="oct-29-2026" tabindex="-1">Oct 29, 2026 <a class="header-anchor" href="#oct-29-2026" aria-label="Permalink to &quot;Oct 29, 2026&quot;">​</a></h2><h3 id="jobs-tell-you-what-to-do-next" tabindex="-1">Jobs tell you what to do next <a class="header-anchor" href="#jobs-tell-you-what-to-do-next" aria-label="Permalink to &quot;Jobs tell you what to do next&quot;">​</a></h3><ul><li>Every job shows a <strong>next-step banner</strong> under the plate, for example &quot;Add quote lines, start canvass, or start work.&quot; or &quot;Collect PHP 800.00 from customer before release.&quot; (<a href="/rakkii-cars-guide/chapters/05-lane-1-private-walk-in-jobs#next-step">Chapter 5</a>).</li><li>Technicians get their own banner: &quot;Finish the bay checklist (1 step left), then send to QC.&quot; (<a href="/rakkii-cars-guide/chapters/02-technician-daily-guide">Chapter 2</a>).</li><li>A waiting customer payment proof shows on the banner and on the <strong>Pay</strong> and <strong>Release</strong> tabs, with a link to <strong>Finance › Payments</strong>.</li></ul><h3 id="qc-photos-lock-ready-for-pickup" tabindex="-1">QC photos lock Ready for pickup <a class="header-anchor" href="#qc-photos-lock-ready-for-pickup" aria-label="Permalink to &quot;QC photos lock Ready for pickup&quot;">​</a></h3><ul><li>While QC photos are missing, <strong>Send to QC</strong> is the main button and <strong>Ready for pickup</strong> is greyed out with the reason (&quot;Need 4 QC photos before Ready/Released (have 0).&quot;).</li></ul><h3 id="quotes-and-margin" tabindex="-1">Quotes and margin <a class="header-anchor" href="#quotes-and-margin" aria-label="Permalink to &quot;Quotes and margin&quot;">​</a></h3><ul><li>If work lines change after a quote, the Quote and Work tabs warn &quot;Work lines changed since the last quote…&quot;.</li><li>Margin is labelled <strong>on cost</strong>: (sell − cost) ÷ cost. The shop&#39;s minimum margin uses the same basis.</li></ul><h3 id="insurance" tabindex="-1">Insurance <a class="header-anchor" href="#insurance" aria-label="Permalink to &quot;Insurance&quot;">​</a></h3><ul><li><strong>Waiting for LOA</strong> now offers <strong>Mark authorized</strong>, <strong>Start work (cash / no LOA)</strong>, <strong>Back to quote</strong>, <strong>Put on hold</strong> and <strong>Cancel job</strong> (<a href="/rakkii-cars-guide/chapters/06-lane-2-insurance-claims-and-loa">Chapter 6</a>).</li><li><strong>Release of Claim</strong>, <strong>Print gate pass</strong> and <strong>Print customer invoice</strong> are on the <strong>Release</strong> tab.</li></ul><h3 id="desk" tabindex="-1">Desk <a class="header-anchor" href="#desk" aria-label="Permalink to &quot;Desk&quot;">​</a></h3><ul><li><strong>New job</strong> asks for the customer, car and work first. Picking a customer on file shows their cars as chips to fill the vehicle.</li><li>&quot;Promised date&quot; is now <strong>Target date</strong>. The <strong>Appointment</strong> (when the car comes in) is a separate date.</li><li><strong>Priority jobs</strong> on the Dashboard, a <strong>search box</strong> in the top bar, and a <strong>Customer activity</strong> feed with a bell count (<a href="/rakkii-cars-guide/chapters/10-workshop-operations-board-calendar-backjobs-contractors">Chapter 10</a>).</li><li>Hard-to-undo actions (create quote, post invoice, record payment, release, approve leave) ask you to confirm.</li></ul><h3 id="hr" tabindex="-1">HR <a class="header-anchor" href="#hr" aria-label="Permalink to &quot;HR&quot;">​</a></h3><ul><li><strong>This week</strong> is Monday to Sunday on Attendance, Payroll and My week.</li><li>Dates read &quot;Oct 29, 2026&quot; everywhere; leave ranges read &quot;Oct 26 – 28, 2026&quot;.</li><li>The <strong>Approve leave</strong> dialog lists the person&#39;s open jobs so you can reassign them.</li><li>The public shop email is <strong><a href="mailto:rakkiicars@gmail.com" target="_blank" rel="noreferrer">rakkiicars@gmail.com</a></strong>.</li></ul><h2 id="a-day-in-the-shop-one-job-from-intake-to-release" tabindex="-1">A day in the shop: one job from intake to release <a class="header-anchor" href="#a-day-in-the-shop-one-job-from-intake-to-release" aria-label="Permalink to &quot;A day in the shop: one job from intake to release&quot;">​</a></h2><p>This is the path we tested end to end on the integration app on Oct 29, 2026, with the Owner and a Lead Technician. Follow it to practise.</p><table tabindex="0"><thead><tr><th>#</th><th>Who</th><th>Where</th><th>What</th></tr></thead><tbody><tr><td>1</td><td>Owner</td><td><strong>Workshop › New job</strong></td><td>Customer, mobile, plate, make, model, year → <strong>Create job</strong>. Status <strong>Booked</strong>.</td></tr><tr><td>2</td><td>Owner</td><td>Job › <strong>Work › Work lines</strong></td><td>Add a labor line (Description, Qty, Cost, Sell) → <strong>Add line</strong>.</td></tr><tr><td>3</td><td>Owner</td><td>Job › <strong>Work › Technicians and dates</strong></td><td>Tick the technician → <strong>Save technicians</strong>. The change is in <strong>Assignment history</strong>.</td></tr><tr><td>4</td><td>Owner</td><td>Job › <strong>Create quote</strong></td><td>Confirm. Status <strong>Quoted</strong>, margin chip &quot;Margin 167% on cost&quot;.</td></tr><tr><td>5</td><td>Owner</td><td>Job header</td><td><strong>Start work</strong>. Status <strong>Under repair</strong>; <strong>Ready for pickup</strong> is locked until the QC photos are in.</td></tr><tr><td>6</td><td>Technician</td><td><strong>My jobs</strong> → the plate</td><td>Add and tick a <strong>Bay checklist</strong> step. Banner: &quot;Send the car to QC when the work is done.&quot;</td></tr><tr><td>7</td><td>Technician</td><td>Job header</td><td><strong>Send to QC</strong>. Status <strong>Quality check</strong>.</td></tr><tr><td>8</td><td>Technician</td><td><strong>Work › QC photos</strong></td><td>Upload <strong>Front</strong>, <strong>Rear</strong>, <strong>Left side (LS)</strong>, <strong>Right side (RS)</strong>. Banner: &quot;QC photos are done. The desk marks the car ready for pickup.&quot;</td></tr><tr><td>9</td><td>Technician</td><td><strong>Me › Leave</strong></td><td><strong>Request leave</strong> for a day.</td></tr><tr><td>10</td><td>Owner</td><td><strong>HR › Clock kiosk</strong></td><td>Tap the technician to clock them in; check it in <strong>HR › Attendance</strong>.</td></tr><tr><td>11</td><td>Owner</td><td>Job header</td><td><strong>Ready for pickup</strong>. Banner: &quot;Collect PHP 800.00 from customer before release.&quot;</td></tr><tr><td>12</td><td>Owner</td><td>Job › <strong>Pay</strong></td><td><strong>Bill customer</strong> → <strong>Create invoice</strong>, then <strong>Record payment</strong> (Cash). Customer owes PHP 0.00.</td></tr><tr><td>13</td><td>Owner</td><td>Job › <strong>Release</strong></td><td>Tick <strong>Keys logged</strong>, <strong>Documents in / out</strong>, <strong>Customer signed release</strong> → <strong>Release car</strong>.</td></tr><tr><td>14</td><td>Owner</td><td><strong>HR › Leave approvals</strong></td><td><strong>Approve</strong> the technician&#39;s leave; keep or reassign their open jobs → <strong>Approve leave</strong>.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Practice data only</p><p>Use made-up customers and plates on the integration app. Never enter real customer names, phone numbers or plates.</p></div>',19)])])}const p=e(n,[["render",s]]);export{u as __pageData,p as default};
